<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>Snake</title>
  <style>
    :root {
      --bg: #0b0f14;
      --panel: #141b24;
      --ink: #e8eef6;
      --muted: #8b9bb0;
      --accent: #3ddc84;
      --danger: #ff5c7a;
      --btn: #1e2836;
      --btn-hover: #2a3648;
    }
    * { box-sizing: border-box; }
    html, body {
      margin: 0;
      min-height: 100%;
      background: radial-gradient(1200px 700px at 50% -10%, #182232 0%, var(--bg) 55%);
      color: var(--ink);
      font-family: system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
    }
    body {
      display: flex;
      align-items: center;
      justify-content: center;
      min-height: 100vh;
      padding: 24px;
    }
    .app {
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 14px;
      background: var(--panel);
      border: 1px solid #243044;
      border-radius: 18px;
      padding: 22px 22px 18px;
      box-shadow: 0 20px 60px rgba(0, 0, 0, 0.35);
    }
    h1 {
      margin: 0;
      font-size: 22px;
      letter-spacing: 0.18em;
      text-transform: uppercase;
      color: var(--accent);
      font-weight: 700;
    }
    .hud {
      width: 400px;
      display: flex;
      justify-content: space-between;
      align-items: baseline;
      color: var(--muted);
      font-size: 14px;
    }
    #score {
      color: var(--ink);
      font-variant-numeric: tabular-nums;
      font-weight: 700;
      font-size: 22px;
    }
    #snake {
      width: 400px;
      height: 400px;
      display: block;
      border-radius: 10px;
      background: #0a1018;
      box-shadow: inset 0 0 0 1px #223047;
    }
    .controls {
      display: flex;
      gap: 10px;
    }
    button {
      appearance: none;
      border: 1px solid #33455d;
      background: var(--btn);
      color: var(--ink);
      font: inherit;
      font-weight: 600;
      padding: 8px 16px;
      border-radius: 10px;
      cursor: pointer;
      min-width: 88px;
    }
    button:hover { background: var(--btn-hover); }
    button:active { transform: translateY(1px); }
    #start { border-color: #2e6b4a; color: var(--accent); }
    #pause { border-color: #6b5a2e; color: #f0c14b; }
    #reset { border-color: #6b2e3d; color: var(--danger); }
    .hint { color: var(--muted); font-size: 12px; }
  </style>
</head>
<body>
  <div class="app">
    <h1>Snake</h1>
    <div class="hud">
      <span>Use arrow keys</span>
      <div>Score: <span id="score">0</span></div>
    </div>
    <canvas id="snake" width="400" height="400"></canvas>
    <div class="controls">
      <button id="start" type="button">Start</button>
      <button id="pause" type="button">Pause</button>
      <button id="reset" type="button">Reset</button>
    </div>
    <div class="hint">Don't hit the walls or yourself. No 180° turns.</div>
  </div>
  <script>
    (function () {
      const W = 20;
      const H = 20;
      const CSS_SIZE = 400;
      const TICK_MS = 110;
      const DIRS = {
        up: [0, -1],
        down: [0, 1],
        left: [-1, 0],
        right: [1, 0]
      };
      const OPP = { up: "down", down: "up", left: "right", right: "left" };

      const canvas = document.getElementById("snake");
      const scoreEl = document.getElementById("score");
      const ctx = canvas.getContext("2d");
      const dpr = Math.max(1, window.devicePixelRatio || 1);
      canvas.width = Math.round(CSS_SIZE * dpr);
      canvas.height = Math.round(CSS_SIZE * dpr);
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

      const cell = CSS_SIZE / W;

      let segments = [];
      let dir = "right";
      let queued = "right";
      let foodPos = [0, 0];
      let isAlive = true;
      let points = 0;
      let timer = null;

      function copySnake() {
        return segments.map(function (p) { return [p[0], p[1]]; });
      }

      function occupiedSet() {
        const s = new Set();
        for (let i = 0; i < segments.length; i++) {
          s.add(segments[i][0] + "," + segments[i][1]);
        }
        return s;
      }

      function placeFoodRandom() {
        const used = occupiedSet();
        const free = [];
        for (let y = 0; y < H; y++) {
          for (let x = 0; x < W; x++) {
            if (!used.has(x + "," + y)) free.push([x, y]);
          }
        }
        if (!free.length) {
          foodPos = [0, 0];
          return;
        }
        foodPos = free[(Math.random() * free.length) | 0];
      }

      function updateScore() {
        scoreEl.textContent = String(points);
      }

      function drawRounded(x, y, size, r) {
        const rr = Math.min(r, size / 2);
        ctx.beginPath();
        ctx.moveTo(x + rr, y);
        ctx.arcTo(x + size, y, x + size, y + size, rr);
        ctx.arcTo(x + size, y + size, x, y + size, rr);
        ctx.arcTo(x, y + size, x, y, rr);
        ctx.arcTo(x, y, x + size, y, rr);
        ctx.closePath();
      }

      function draw() {
        ctx.clearRect(0, 0, CSS_SIZE, CSS_SIZE);
        ctx.fillStyle = "#070b11";
        ctx.fillRect(0, 0, CSS_SIZE, CSS_SIZE);

        ctx.strokeStyle = "rgba(80, 110, 145, 0.12)";
        ctx.lineWidth = 1;
        for (let i = 0; i <= W; i++) {
          const p = Math.round(i * cell) + 0.5;
          ctx.beginPath();
          ctx.moveTo(p, 0);
          ctx.lineTo(p, CSS_SIZE);
          ctx.stroke();
          ctx.beginPath();
          ctx.moveTo(0, p);
          ctx.lineTo(CSS_SIZE, p);
          ctx.stroke();
        }

        const fx = foodPos[0] * cell;
        const fy = foodPos[1] * cell;
        const cx = fx + cell / 2;
        const cy = fy + cell / 2;
        const rad = cell * 0.32;
        const glow = ctx.createRadialGradient(cx, cy, 2, cx, cy, cell * 0.7);
        glow.addColorStop(0, "rgba(255, 92, 122, 0.55)");
        glow.addColorStop(1, "rgba(255, 92, 122, 0)");
        ctx.fillStyle = glow;
        ctx.fillRect(fx - 4, fy - 4, cell + 8, cell + 8);
        ctx.fillStyle = "#ff5c7a";
        ctx.beginPath();
        ctx.arc(cx, cy, rad, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = "rgba(255,255,255,0.35)";
        ctx.beginPath();
        ctx.arc(cx - rad * 0.28, cy - rad * 0.28, rad * 0.28, 0, Math.PI * 2);
        ctx.fill();

        for (let i = segments.length - 1; i >= 0; i--) {
          const t = segments.length === 1 ? 0 : i / (segments.length - 1);
          const g = Math.round(220 - t * 90);
          const b = Math.round(130 - t * 50);
          ctx.fillStyle = i === 0 ? "#5cff9f" : "rgb(40," + g + "," + b + ")";
          const pad = i === 0 ? 1.6 : 2.4;
          const x = segments[i][0] * cell + pad;
          const y = segments[i][1] * cell + pad;
          const s = cell - pad * 2;
          drawRounded(x, y, s, 6);
          ctx.fill();
        }

        if (segments.length) {
          const head = segments[0];
          const hx = head[0] * cell + cell / 2;
          const hy = head[1] * cell + cell / 2;
          const v = DIRS[dir];
          const px = -v[1];
          const py = v[0];
          const eye = cell * 0.09;
          const fwd = cell * 0.14;
          const side = cell * 0.16;
          ctx.fillStyle = "#0b0f14";
          ctx.beginPath();
          ctx.arc(hx + v[0] * fwd + px * side, hy + v[1] * fwd + py * side, eye, 0, Math.PI * 2);
          ctx.arc(hx + v[0] * fwd - px * side, hy + v[1] * fwd - py * side, eye, 0, Math.PI * 2);
          ctx.fill();
        }

        if (!isAlive) {
          ctx.fillStyle = "rgba(7, 11, 17, 0.55)";
          ctx.fillRect(0, 0, CSS_SIZE, CSS_SIZE);
          ctx.fillStyle = "#ff5c7a";
          ctx.font = "700 28px system-ui, sans-serif";
          ctx.textAlign = "center";
          ctx.textBaseline = "middle";
          ctx.fillText("Game Over", CSS_SIZE / 2, CSS_SIZE / 2 - 10);
          ctx.fillStyle = "#e8eef6";
          ctx.font = "500 14px system-ui, sans-serif";
          ctx.fillText("Press Reset to play again", CSS_SIZE / 2, CSS_SIZE / 2 + 20);
        }
      }

      function reset() {
        stopLoop();
        isAlive = true;
        points = 0;
        dir = "right";
        queued = "right";
        const midY = (H / 2) | 0;
        const midX = (W / 2) | 0;
        segments = [
          [midX, midY],
          [midX - 1, midY],
          [midX - 2, midY]
        ];
        placeFoodRandom();
        updateScore();
        draw();
      }

      function tick() {
        if (!isAlive) return;
        dir = queued;
        const v = DIRS[dir];
        const head = segments[0];
        const nx = head[0] + v[0];
        const ny = head[1] + v[1];

        if (nx < 0 || ny < 0 || nx >= W || ny >= H) {
          isAlive = false;
          stopLoop();
          draw();
          return;
        }

        const eating = foodPos && nx === foodPos[0] && ny === foodPos[1];
        const limit = eating ? segments.length : segments.length - 1;
        for (let i = 0; i < limit; i++) {
          if (segments[i][0] === nx && segments[i][1] === ny) {
            isAlive = false;
            stopLoop();
            draw();
            return;
          }
        }

        segments.unshift([nx, ny]);
        if (eating) {
          points += 1;
          updateScore();
          placeFoodRandom();
        } else {
          segments.pop();
        }
        draw();
      }

      function setDir(name) {
        if (name !== "up" && name !== "down" && name !== "left" && name !== "right") return;
        if (OPP[queued] === name) return;
        if (OPP[dir] === name) return;
        queued = name;
      }

      function setFood(x, y) {
        foodPos = [x, y];
        draw();
      }

      function stopLoop() {
        if (timer !== null) {
          clearInterval(timer);
          timer = null;
        }
      }

      function startLoop() {
        if (!isAlive) return;
        if (timer !== null) return;
        timer = setInterval(tick, TICK_MS);
      }

      document.getElementById("start").addEventListener("click", startLoop);
      document.getElementById("pause").addEventListener("click", stopLoop);
      document.getElementById("reset").addEventListener("click", reset);

      window.addEventListener("keydown", function (e) {
        const map = {
          ArrowUp: "up",
          ArrowDown: "down",
          ArrowLeft: "left",
          ArrowRight: "right"
        };
        const next = map[e.key];
        if (!next) return;
        e.preventDefault();
        setDir(next);
      });

      window.game = {
        w: W,
        h: H,
        reset: reset,
        tick: tick,
        setDir: setDir,
        setFood: setFood,
        snake: function () { return copySnake(); },
        food: function () { return [foodPos[0], foodPos[1]]; },
        alive: function () { return isAlive; },
        score: function () { return points; }
      };

      reset();
    })();
  </script>
</body>
</html>
